         const wk = {
             ...baseWk,
             [M_AUTHENTICATION.stable!]: {
                 issuer: "test.com",
             },
         };
         expect(validateWellKnownAuthentication(wk[M_AUTHENTICATION.stable!])).toEqual({
             issuer: "test.com",
         });
     });

     it("should remove unexpected properties", () => {
         const wk = {
             ...baseWk,
             [M_AUTHENTICATION.stable!]: {
                 issuer: "test.com",
                 somethingElse: "test",
             },
         };
         expect(validateWellKnownAuthentication(wk[M_AUTHENTICATION.stable!])).toEqual({
             issuer: "test.com",
